const scenario = $.Trigger.scenario;

const config = {
  pool: {
    response: $.Steps.Launch_AAP_Pool_Fault,
    templateId: '21',
    templateName: 'Pool Fault',
    action: 'pool'
  },
  disk: {
    response: $.Steps.Launch_AAP_Disk_Fault,
    templateId: '22',
    templateName: 'Disk Fault',
    action: 'disk'
  },
  reset: {
    response: $.Steps.Launch_AAP_Reset_Demo,
    templateId: '15',
    templateName: 'Reset Demo',
    action: 'reset'
  },
  autoscale: {
    response: $.Steps.Launch_AAP_Autoscale_Fault,
    templateId: '31',
    templateName: 'Inject Storefront Traffic Spike',
    action: 'autoscale'
  },
  rollback: {
    response: $.Steps.Launch_AAP_Rollback_Fault,
    templateId: '29',
    templateName: 'Deploy Storefront Demo-Bad',
    action: 'rollback'
  }
};

const selected = config[scenario] || {};
const response = selected.response || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);
const jobId = body.id !== undefined && body.id !== null ? String(body.id) : '';
const rawState = String(body.status || 'pending');
const accepted = httpStatus === 201 && jobId !== '';

$.Helpers.setVariable('execution_backend', 'AAP');
$.Helpers.setVariable('job_id', jobId);
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('aap_job_template_id', selected.templateId || '');
$.Helpers.setVariable('aap_job_template_name', selected.templateName || '');
$.Helpers.setVariable('job_action', selected.action || '');
$.Helpers.setVariable('launch_http_status', httpStatus);
$.Helpers.setVariable(
  'failure_reason',
  accepted ? '' : 'AAP did not return HTTP 201 with a valid job ID'
);

return {
  accepted,
  backend: 'AAP',
  http_status: httpStatus,
  job_id: jobId,
  raw_state: rawState
};

const scenario = $.Trigger.scenario;
const config = {
  memory: { backend: 'AAP', response: $.Steps.Launch_AAP_Memory_Fault, action: 'memory', templateId: '33', templateName: 'Inject Memory Pressure' },
  'reset-memory': { backend: 'AAP', response: $.Steps.Launch_AAP_Reset_Memory, action: 'reset-memory', templateId: '35', templateName: 'Restore Memory Baseline' }
};
const selected = config[scenario] || {};
const response = selected.response || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);
let jobId = '';
let rawState = '';
let accepted = false;
if (selected.backend === 'AAP') {
  jobId = body.id !== undefined && body.id !== null ? String(body.id) : '';
  rawState = String(body.status || 'pending');
  accepted = httpStatus === 201 && /^[1-9][0-9]*$/.test(jobId);
}
$.Helpers.setVariable('execution_backend', selected.backend || 'UNKNOWN');
$.Helpers.setVariable('job_id', jobId);
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('aap_job_template_id', selected.templateId || '');
$.Helpers.setVariable('aap_job_template_name', selected.templateName || '');
$.Helpers.setVariable('job_action', selected.action || '');
$.Helpers.setVariable('launch_http_status', httpStatus);
$.Helpers.setVariable('failure_reason', accepted ? '' : 'AAP did not return the expected Job Template launch response');
return { accepted, backend: selected.backend || 'UNKNOWN', http_status: httpStatus, job_id: jobId, raw_state: rawState };

const expectedJobId = String($.Variables.job_id || '');
const response = $.Steps.Get_AAP_Job_Status || {};
const body = response.body || {};
const responseJobId =
  body.id !== undefined && body.id !== null ? String(body.id) : '';

const valid =
  Number(response.status || 0) === 200 &&
  responseJobId === expectedJobId;
const rawState = String(body.status || '');
let normalizedState = 'unexpected';
let detail = '';
if (valid) $.Helpers.setVariable('aap_job_artifacts', body.artifacts || {});

if (['pending', 'waiting', 'running'].includes(rawState)) {
  normalizedState = 'running';
} else if (rawState === 'successful') {
  normalizedState = 'succeeded';
} else if (['failed', 'error', 'canceled'].includes(rawState)) {
  normalizedState = 'failed';
  detail = 'AAP terminal state: ' + rawState;
}

$.Helpers.setVariable('status_response_valid', valid);
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('job_state', normalizedState);

if (normalizedState === 'failed' && detail) {
  $.Helpers.setVariable('failure_reason', detail);
}

return {
  valid,
  backend: 'AAP',
  raw_state: rawState,
  normalized_state: normalizedState,
  detail
};

const currentCount = $.Variables.poll_count || 0;
const newCount = currentCount + 1;
$.Helpers.setVariable('poll_count', newCount);
return newCount;

let passed = true;
let reason = '';
if ($.Trigger.scenario === 'reset-memory') {
  const a = $.Variables.aap_job_artifacts || {};
  const changed = a.poc_restore_changed === true || a.poc_restore_changed === 'true';
  const unchanged = a.poc_restore_changed === false || a.poc_restore_changed === 'false';
  const after = Number(a.poc_memory_after_gib);
  const current = Number(a.poc_memory_current_gib);
  passed = (changed && Number.isFinite(after) && after >= 15 && after <= 17) ||
    (unchanged && current === 16 && Number(a.poc_memory_baseline_gib) === 16);
  if (!passed) reason = 'JT 35 succeeded but artifacts do not demonstrate the 16 GiB baseline. Below-baseline no-change is not a successful restore. Review AAP output; no automatic relaunch.';
}
$.Helpers.setVariable('workflow_result', passed ? 'ACTION_SUCCEEDED' : 'RESET_EVIDENCE_FAILED');
$.Helpers.setVariable('failure_reason', reason);
return {passed, reason};

const response = $.Steps.Launch_Memory_Reset_Preparation || {};
const body = response.body || {};
const id = String(body.id || '');
const accepted = Number(response.status) === 201 && /^[1-9][0-9]*$/.test(id);
$.Helpers.setVariable('job_id', id);
$.Helpers.setVariable('memory_cleanup_job_id', id);
$.Helpers.setVariable('execution_backend', 'AAP');
$.Helpers.setVariable('aap_job_template_id', '15');
$.Helpers.setVariable('aap_job_template_name', 'Reset Demo before Memory Restore');
$.Helpers.setVariable('job_action', 'reset');
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', String(body.status || 'pending'));
$.Helpers.setVariable('failure_reason', accepted ? '' : 'JT 15 cleanup launch was not accepted; JT 35 was not launched');
return {accepted};

const expectedJobId = String($.Variables.job_id || '');
const response = $.Steps.Get_AAP_Job_Status_Prepare || {};
const body = response.body || {};
const responseJobId =
  body.id !== undefined && body.id !== null ? String(body.id) : '';

const valid =
  Number(response.status || 0) === 200 &&
  responseJobId === expectedJobId;
const rawState = String(body.status || '');
let normalizedState = 'unexpected';
let detail = '';

if (['pending', 'waiting', 'running'].includes(rawState)) {
  normalizedState = 'running';
} else if (rawState === 'successful') {
  normalizedState = 'succeeded';
} else if (['failed', 'error', 'canceled'].includes(rawState)) {
  normalizedState = 'failed';
  detail = 'AAP terminal state: ' + rawState;
}

$.Helpers.setVariable('status_response_valid', valid);
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('job_state', normalizedState);

if (normalizedState === 'failed' && detail) {
  $.Helpers.setVariable('failure_reason', detail);
}

return {
  valid,
  backend: 'AAP',
  raw_state: rawState,
  normalized_state: normalizedState,
  detail
};

const currentCount = $.Variables.poll_count || 0;
const newCount = currentCount + 1;
$.Helpers.setVariable('poll_count', newCount);
return newCount;
